import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_ARTICULO } from '../../models/tienda-articulo.model.mjs';
import { MODELO_VENDEDOR, MODELO_ASIGNACION } from '../../models/vendedor-asignacion.model.mjs';

export async function buscarArticuloRepository(articuloId) {
  const { Item } = await MODELO_ARTICULO.build(EntityRepository).get(
    { articuloId },
    { consistent: true }
  );
  return Item;
}

export async function buscarVendedorRepository(vendedorId) {
  const { Item } = await MODELO_VENDEDOR.build(EntityRepository).get(
    { vendedorId },
    { consistent: true }
  );
  return Item;
}

export async function asignarVendedorRepository(articuloId, vendedorId, rol) {
  const asignacion = { articuloId, vendedorId, rol };
  await MODELO_ASIGNACION.build(EntityRepository).put(
    asignacion,
    { condition: { attr: 'articuloId', exists: false } }
  );
  return asignacion;
}

import { buscarArticuloRepository, buscarVendedorRepository, asignarVendedorRepository } from './repository.mjs';

export class ReferenciaInexistenteError extends Error {}

export async function asignarVendedorService(articuloId, vendedorId, rol) {
  const articulo = await buscarArticuloRepository(articuloId);
  const vendedor = await buscarVendedorRepository(vendedorId);
  if (!articulo || !vendedor) {
    throw new ReferenciaInexistenteError('No existe el articulo o el vendedor');
  }
  return asignarVendedorRepository(articuloId, vendedorId, rol);
}

import { asignarVendedorService, ReferenciaInexistenteError } from './service.mjs';

export async function handler(event) {
  const articuloId = Number(event.pathParameters.articuloId);
  const { vendedorId, rol } = JSON.parse(event.body);
  try {
    const asignacion = await asignarVendedorService(articuloId, vendedorId, rol);
    return { statusCode: 201, body: JSON.stringify(asignacion) };
  } catch (error) {
    if (error instanceof ReferenciaInexistenteError) {
      return { statusCode: 404, body: JSON.stringify({ message: error.message }) };
    }
    if (error.name === 'ConditionalCheckFailedException') {
      return { statusCode: 409, body: JSON.stringify({ message: 'El vendedor ya está asignado a ese articulo' }) };
    }
    throw error;
  }
}

